#include <iostream>
#include <vector>
using namespace std;

int main() {
    int n, h;
    cin >> n >> h;
    vector<long long> s(n + 1, 1);
    vector<long long> t = s;
    for (int m = 1; m <= n; ++m) {
        long long sum_val = 0;
        for (int k = 0; k < m; ++k) {
            sum_val += s[m - 1 - k] * s[k];
        }
        s[m] = sum_val;
    }
    for (int _ = 0; _ < h; ++_) {
        vector<long long> t_new;
        for (int m = 0; m <= n; ++m) {
            long long total = 0;
            for (int k = 0; k < m; ++k) {
                total += (s[k] - t[k]) * t[m - 1 - k] + s[m - 1 - k] * t[k];
            }
            t_new.push_back(total);
        }
        t = t_new;
    }
    cout << t[n] << "\n";
    return 0;
}
